"use strict";function openQuickPreviewModal(t){var e=openModal(modalShell({icon:"fa-regular fa-eye",kicker:"Ticket \xB7 vista r\xE1pida",title:"Vista previa r\xE1pida",titleChip:t.ticket_number,width:"md",body:'<div class="tkt-side-rows">'+sideRow("Cliente",t.customer?t.customer.name:"Sin cliente")+sideRow("Asunto",t.subject||"(sin asunto)")+sideRow("Estado",t.status_name||t.status_slug||"\u2014",{strong:!0})+sideRow("Prioridad",priorityLabel(t.priority),{strong:!0})+sideRow("SLA",t.sla_text||"\u2014",{mono:!0,last:!0})+"</div>"+(t.last_message_snippet?'<div class="tkt-field"><label class="tkt-label">\xDAltimo mensaje</label><div class="tkt-tpl-preview">'+escapeHtml(t.last_message_snippet)+"</div></div>":"")+'<div class="tkt-note"><i class="fa-solid fa-circle-info"></i> Navega con <span class="mono">J</span> / <span class="mono">K</span> sin cerrar la vista previa.</div>',foot:'<button type="button" class="tkt-btn tkt-btn-primary" id="tkt-qp-open">Abrir completo</button><button type="button" class="tkt-btn" id="tkt-qp-reply">Responder</button><button type="button" class="tkt-btn" data-modal-close>Cerrar</button>'}));e.on("click","#tkt-qp-open",function(){closeModal(),selectTicket(t)}),e.on("click","#tkt-qp-reply",function(){closeModal(),selectTicket(t),openComposeModal(t)})}
